mapper.select:
select progress_seconds, total_duration
from sys_play_progress
where user_id = #{userId}
  and episode_id = #{episodeId}

mapper.update:
update sys_play_progress
set progress_seconds = #{progress},
    total_duration = #{duration},
    updated_at = now()
where user_id = #{userId}
  and episode_id = #{episodeId}
